&lt;li&gt;&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly93d3cubWFubmluZy5jb20vYm9va3MvYnVpbGQtYS1sYXJnZS1sYW5ndWFnZS1tb2RlbC1mcm9tLXNjcmF0Y2g=&#34;&gt;https://www.manning.com/books/build-a-large-language-model-from-scratch&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
