&lt;li&gt;&lt;a href=&#34;https://twitter.com/devploit&#34;&gt;&lt;strong&gt;devploit&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://www.gnu.org/software/bash/manual/html_node/Shell-Builtin-Commands.html&#34;&gt;&lt;strong&gt;shell builtins&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly9naXRodWIuY29tL0JvMG9NL1dBRi1ieXBhc3MtQ2hlYXQtU2hlZXQ=&#34;&gt;https://github.com/Bo0oM/WAF - 绕过 - Cheat-Sheet&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly9ibG9nLnRyYWlsb2ZiaXRzLmNvbS8yMDI1LzA3LzI1L2V4cGxvaXRpbmctemVyby1kYXlzLWluLWFiYW5kb25lZC1oYXJkd2FyZS8=&#34;&gt;Exploiting zero days in abandoned hardware – Trail of Bits blog&lt;/span&gt;&lt;/li&gt;
