&lt;ul&gt;
&lt;li&gt;&lt;a href=&#34;https://www.youtube.com/watch?v=poHirez8jk4&#34;&gt;&lt;strong&gt;DEF CON 31：Exploring Linux Memory Manipulation for Stealth and 规避&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/nnsee/fileless-elf-exec&#34;&gt;&lt;strong&gt;fileless-elf-exec&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/arget13/DDexec&#34;&gt;&lt;strong&gt;DDexec / EverythingExec&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/arget13/memexec&#34;&gt;&lt;strong&gt;Memexec&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly9naXRodWIuY29tL2FyZ2V0MTMvbWVtZXhlYy9ibG9iL21haW4vYS5waHA=&#34;&gt;https://github.com/arget13/memexec/blob/main/a.php&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/arget13/memdlopen&#34;&gt;&lt;strong&gt;memdlopen&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/carlospolop/DistrolessRCE&#34;&gt;&lt;strong&gt;https://github.com/carlospolop/DistrolessRCE&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;检查清单&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#检查清单&#34;&gt;#&lt;/a&gt; 检查清单&lt;/h2&gt;
&lt;ul class=&#34;task-list&#34;&gt;
&lt;li class=&#34;task-list-item&#34;&gt;&lt;input type=&#34;checkbox&#34; id=&#34;cbx_0&#34; disabled=&#34;true&#34; /&gt;&lt;label for=&#34;cbx_0&#34;&gt; 是否提取进程链 / 命令行 / 网络 / 文件 / 日志线索&lt;/label&gt;&lt;/li&gt;
&lt;li class=&#34;task-list-item&#34;&gt;&lt;input type=&#34;checkbox&#34; id=&#34;cbx_1&#34; disabled=&#34;true&#34; /&gt;&lt;label for=&#34;cbx_1&#34;&gt; 是否区分攻击行为和正常管理行为&lt;/label&gt;&lt;/li&gt;
&lt;li class=&#34;task-list-item&#34;&gt;&lt;input type=&#34;checkbox&#34; id=&#34;cbx_2&#34; disabled=&#34;true&#34; /&gt;&lt;label for=&#34;cbx_2&#34;&gt; 是否记录绕过假设与限制&lt;/label&gt;&lt;/li&gt;
&lt;li class=&#34;task-list-item&#34;&gt;&lt;input type=&#34;checkbox&#34; id=&#34;cbx_3&#34; disabled=&#34;true&#34; /&gt;&lt;label for=&#34;cbx_3&#34;&gt; 是否形成检测规则或查询语句&lt;/label&gt;&lt;/li&gt;
