&lt;li&gt;&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly9wb3J0c3dpZ2dlci5uZXQvd2ViLXNlY3VyaXR5L29zLWNvbW1hbmQtaW5qZWN0aW9uL2xhYi1ibGluZC1vdXRwdXQtcmVkaXJlY3Rpb24=&#34;&gt;PortSwigger：Blind OS 命令注入 with output redirection&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly9wb3J0c3dpZ2dlci5uZXQvd2ViLXNlY3VyaXR5L29zLWNvbW1hbmQtaW5qZWN0aW9uL2xhYi1ibGluZC1vdXQtb2YtYmFuZA==&#34;&gt;PortSwigger：Blind OS 命令注入 with out-of-band interaction&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly9wb3J0c3dpZ2dlci5uZXQvd2ViLXNlY3VyaXR5L29zLWNvbW1hbmQtaW5qZWN0aW9uL2xhYi1ibGluZC1vdXQtb2YtYmFuZC1kYXRhLWV4ZmlsdHJhdGlvbg==&#34;&gt;PortSwigger：Blind OS 命令注入 with out-of-band data exfiltration&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly93d3cucm9vdC1tZS5vcmcvZW4vQ2hhbGxlbmdlcy9XZWItU2VydmVyL1BIUC1Db21tYW5kLWluamVjdGlvbg==&#34;&gt;Root Me：PHP：命令注入&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly93d3cucm9vdC1tZS5vcmcvZW4vQ2hhbGxlbmdlcy9XZWItU2VydmVyL0NvbW1hbmQtaW5qZWN0aW9uLUZpbHRlci1ieXBhc3M=&#34;&gt;Root Me：命令注入：Filter 绕过&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly93d3cucm9vdC1tZS5vcmcvZW4vQ2hhbGxlbmdlcy9XZWItU2VydmVyL1BIUC1hc3NlcnQ=&#34;&gt;Root Me：PHP：assert()&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly93d3cucm9vdC1tZS5vcmcvZW4vQ2hhbGxlbmdlcy9XZWItU2VydmVyL1BIUC1wcmVnX3JlcGxhY2U=&#34;&gt;Root Me：PHP：preg replace()&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly93ZWIuYXJjaGl2ZS5vcmcvd2ViLzIwMjUxMjExMjEyMDQ2L2h0dHBzOi8vc29uYXJzb3VyY2UuZ2l0aHViLmlvL2FyZ3VtZW50LWluamVjdGlvbi12ZWN0b3JzLw==&#34;&gt;Argument Injection Vectors：SonarSource：February 21, 2023&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly93ZWIuYXJjaGl2ZS5vcmcvd2ViLzIwMTQwNzE0MTQwNDM3L2h0dHA6Ly93d3cuZXhwbG9pdC1kYi5jb20vcGFwZXJzLzMzOTMw&#34;&gt;Back to the Future: Unix Wildcards Gone Wild：Leon Juranic：June 25, 2014&lt;/span&gt;&lt;/li&gt;
