&lt;li&gt;&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly93d3cueW91dHViZS5jb20vd2F0Y2g/dj1tRzcxNUhjRGdPOA==&#34;&gt;https://www.youtube.com/watch?v=mG715HcDgO8&lt;/span&gt;&lt;/li&gt;
