27;alert&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;[&lt;span class=&#34;number&#34;&gt;7&lt;/span&gt;].&lt;span class=&#34;title function_&#34;&gt;map&lt;/span&gt;(alert)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;[&lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;].&lt;span class=&#34;title function_&#34;&gt;find&lt;/span&gt;(alert)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;[&lt;span class=&#34;number&#34;&gt;9&lt;/span&gt;].&lt;span class=&#34;title function_&#34;&gt;every&lt;/span&gt;(alert)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;[&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;].&lt;span class=&#34;title function_&#34;&gt;filter&lt;/span&gt;(alert)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;[&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;].&lt;span class=&#34;title function_&#34;&gt;findIndex&lt;/span&gt;(alert)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;[&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;].&lt;span class=&#34;title function_&#34;&gt;forEach&lt;/span&gt;(alert);&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/p&gt;
&lt;h3 id=&#34;17-绕过-using-an-alternate-way-to-execute-an-alert&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#17-绕过-using-an-alternate-way-to-execute-an-alert&#34;&gt;#&lt;/a&gt; 17. 绕过 using an Alternate Way to Execute an Alert&lt;/h3&gt;
&lt;p&gt;&lt;figure class=&#34;highlight javascript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;c=&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;; &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt;(i &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; self) &amp;#123; &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt;(i == &lt;span class=&#34;string&#34;&gt;&amp;quot;alert&amp;quot;&lt;/span&gt;) &amp;#123; &lt;span class=&#34;variable language_&#34;&gt;console&lt;/span&gt;.&lt;span class=&#34;title function_&#34;&gt;log&lt;/span&gt;(c); &amp;#125; c++; &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 5&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/p&gt;
&lt;h3 id=&#34;18-绕过-using-an-alternate-way-to-execute-an-alert&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#18-绕过-using-an-alternate-way-to-execute-an-alert&#34;&gt;#&lt;/a&gt; 18. 绕过 using an Alternate Way to Execute an Alert&lt;/h3&gt;
&lt;p&gt;&lt;figure class=&#34;highlight javascript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;title class_&#34;&gt;Object&lt;/span&gt;.&lt;span class=&#34;title function_&#34;&gt;keys&lt;/span&gt;(self)[&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// &amp;quot;alert&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;self[&lt;span class=&#34;title class_&#34;&gt;Object&lt;/span&gt;.&lt;span class=&#34;title function_&#34;&gt;keys&lt;/span&gt;(self)[&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;]](&lt;span class=&#34;string&#34;&gt;&amp;quot;1&amp;quot;&lt;/span&gt;) &lt;span class=&#34;comment&#34;&gt;// alert(&amp;quot;1&amp;quot;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/p&gt;
