&lt;li&gt;&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly9wb3J0c3dpZ2dlci5uZXQvdXJsLWNoZWF0LXNoZWV0I2lkPTFkYTJmNjI3ZDcwMjI0OGI5ZTYxY2MyMzkxMmQyYzcyOWU1MmY4Nzg=&#34;&gt;https://example.com[@attacker.com&lt;/span&gt;&lt;/li&gt;
